/* acquire a connection to the GPS device
 * could be serial, udp://, tcp://, etc.
 *
 * Return: fd on success
 *         less than zero on failure
 *         UNALLOCATED_FD (-1)  -- give up
 *         PLACEHOLDING_FD (-2) -- retry possible
 */
int gpsd_activate(struct gps_device_t *session, const int mode)
{
    GPSD_LOG(LOG_PROG, &session->context->errout,
             "CORE: gpsd_activate(%s, %d) fd %d\n",
             session->gpsdata.dev.path, mode,
             session->gpsdata.gps_fd);

    if (O_OPTIMIZE == mode) {
        gpsd_run_device_hook(&session->context->errout,
                             session->gpsdata.dev.path, HOOK_ACTIVATE);
    }
    session->gpsdata.gps_fd = gpsd_open(session);
    if (O_CONTINUE != mode) {
        session->mode = mode;
    }

    if (0 > session->gpsdata.gps_fd) {
        // return could be -1, PLACEHOLDING_FD, of UNALLOCATED_FD
        // could be ntrip:// reconnect in progress
        if (PLACEHOLDING_FD == session->gpsdata.gps_fd &&
            SOURCE_PPS == session->sourcetype &&
            NULL == session->pps_thread.report_hook) {
            // it is /dev/ppsX, need to set devicename, etc.
            // check report_hook to ensure not already running
            GPSD_LOG(LOG_PROG, &session->context->errout,
                     "CORE: to gpsd_clear() fd %d\n",
                     session->gpsdata.gps_fd);
            gpsd_clear(session);
        }
        return session->gpsdata.gps_fd;
    }

#ifdef NON_NMEA0183_ENABLE
    // if it's a sensor, it must be probed
    if ((SERVICE_SENSOR == session->servicetype) &&
            lexer->state = AIS_LEADER_END;
        } else {
            return character_pushback(lexer, GROUND_STATE);
        }
        break;
    case AIS_LEADER_END:
        // We stay here grabbing the body of the message, until \r\n
        if ('\r' == c) {
            lexer->state = AIS_CR;
        } else if ('\n' == c) {
            /* not strictly correct (missing \r), but helps with
             * interpreting logfiles. */
            lexer->state = AIS_RECOGNIZED;
        } else if (!isprint(c)) {
            (void)character_pushback(lexer, GROUND_STATE);
        }
        break;
    case AIS_CR:
        if ('\n' == c) {
            lexer->state = AIS_RECOGNIZED;
        } else {
            (void)character_pushback(lexer, GROUND_STATE);
        }
        break;
    // end of AIS states

#if defined(TNT_ENABLE) || defined(GARMINTXT_ENABLE) || defined(ONCORE_ENABLE)
    case AT1_LEADER:
        switch (c) {
#ifdef ONCORE_ENABLE
        case '@':
            lexer->state = ONCORE_AT2;
            break;
#endif  // ONCORE_ENABLE
#ifdef TNT_ENABLE
        case '*':
            /*
             * TNT has similar structure to NMEA packet, '*' before
             * optional checksum ends the packet. Since '*' cannot be
             * received from GARMIN working in TEXT mode, use this
             * difference to tell that this is not GARMIN TEXT packet,
             * could be TNT.
             */
            lexer->state = NMEA_LEADER_END;
            break;
#endif  // TNT_ENABLE
#if defined(GARMINTXT_ENABLE)
        case '\r':
            /* stay in this state, next character should be '\n' */
            /* in the theory we can stop search here and don't wait for '\n' */
            lexer->state = AT1_LEADER;
            break;
        case '\n':
            // end of packet found
            lexer->state = GTXT_RECOGNIZED;
            break;
#endif  // GARMINTXT_ENABLE
        default:
            if (!isprint(c)) {
                return character_pushback(lexer, GROUND_STATE);
